'use strict';

// Full text of one act (texts/<id>.md, generated by scripts/build_law_texts.py).
// The text is a consultation copy with its own source and hash. This screen
// only reads it: legal state, review depth and applicability come from the
// catalog record and are shown as recorded.
const LawReader = (() => {
  const ID = /^[a-z0-9][a-z0-9-]*$/;
  const ANCHOR = /^[a-z0-9][a-z0-9-]*$/;
  const texts = new Map();
  let indexLoad = null;
  let index = new Map();
  let current = null;

  function route(id, anchor) {
    const values = anchor ? { id, trecho: anchor } : { id };
    return '#lei?' + new URLSearchParams(values);
  }

  function loadIndex() {
    if (!indexLoad)
      indexLoad = fetch('texts/index.json')
        .then((response) => (response.ok ? response.json() : { acts: [] }))
        .then((data) => {
          index = new Map((data.acts || []).map((act) => [act.id, act]));
        })
        .catch(() => {
          index = new Map();
        });
    return indexLoad;
  }

  // True only when the generated index says the act has its full text.
  function has(id) {
    return Boolean(index.get(id)?.fullTextAvailable);
  }

  function parse(markdown) {
    const match = markdown.match(/^---\n([\s\S]*?)\n---\n/);
    const meta = {};
    if (match)
      for (const line of match[1].split('\n')) {
        const at = line.indexOf(': ');
        if (at < 0) continue;
        try {
          meta[line.slice(0, at)] = JSON.parse(line.slice(at + 2));
        } catch {
          // A malformed line leaves that field absent.
        }
      }
    const body = match ? markdown.slice(match[0].length) : markdown;
    const blocks = [];
    for (const raw of body.split(/\n{2,}/)) {
      let text = raw.trim();
      if (!text) continue;
      let id = null;
      const anchor = text.match(/^<a id="([a-z0-9-]+)"><\/a>\s*/);
      if (anchor) {
        id = anchor[1];
        text = text.slice(anchor[0].length);
      }
      if (text.startsWith('# ')) continue; // The page header shows the title.
      if (text.startsWith('---')) {
        blocks.push({ kind: 'rule', id });
        text = text.replace(/^---\s*/, '');
        id = null;
        if (!text) continue;
      }
      if (text.startsWith('## ')) blocks.push({ kind: 'annex', id, text: text.slice(3) });
      else if (text.startsWith('### ')) blocks.push({ kind: 'heading', id, text: text.slice(4) });
      else if (text.startsWith('> ')) blocks.push({ kind: 'notice', id, text: text.slice(2) });
      else blocks.push({ kind: 'text', id, text });
    }
    return { meta, blocks };
  }

  async function load(id) {
    if (!ID.test(id)) throw new Error('Identificador inválido');
    if (!texts.has(id)) {
      const response = await fetch(`texts/${id}.md`);
      if (!response.ok) throw new Error('Texto não encontrado');
      texts.set(id, parse(await response.text()));
    }
    return texts.get(id);
  }

  // Inline subset written by the generator: **label**, *note*, `code`, <url>.
  function inline(text) {
    let html = esc(text);
    html = html.replace(/&lt;(https?:\/\/[^\s&]+)&gt;/g, (_, url) => {
      const link = safeLink(url.replace(/&amp;/g, '&'), 'documento oficial');
      return link || esc(url);
    });
    html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
    html = html.replace(/^\*\*(.+?)\*\*/, '<strong>$1</strong>');
    if (/^\*[^*].*\*$/.test(html)) html = `<em>${html.slice(1, -1)}</em>`;
    return html;
  }

  function levelOf(text) {
    const plain = text.replace(/^\*\*(.+?)\*\*\s*/, '$1 ');
    if (/^(§|Parágrafo único)/.test(plain)) return 'paragraph';
    if (/^[IVXLC]+\s*[-–—]\s/.test(plain)) return 'inciso';
    if (/^[a-z]\)\s/.test(plain)) return 'alinea';
    if (/^\d+(\.\d+)+\.?\s/.test(plain)) return 'item';
    return '';
  }

  function labelOf(block) {
    const match = block.text.match(/^\*\*(.+?)\*\*/);
    return match ? match[1] : '';
  }

  function renderBlocks(id, blocks) {
    return blocks
      .map((block) => {
        const dom = block.id ? ` id="lei-${esc(block.id)}" tabindex="-1"` : '';
        const target = block.id ? ` data-law-anchor="${esc(block.id)}"` : '';
        if (block.kind === 'rule') return `<hr${dom}${target}>`;
        if (block.kind === 'annex')
          return `<h2 class="law-annex"${dom}${target}><a href="${esc(route(id, block.id))}">${esc(block.text)}</a></h2>`;
        if (block.kind === 'heading') return `<h3${dom}${target}>${esc(block.text)}</h3>`;
        if (block.kind === 'notice')
          return `<p class="notice portal-consultation-note"${dom}>${inline(block.text)}</p>`;
        const level = levelOf(block.text);
        let html = inline(block.text);
        // The device label is the link to the device itself.
        if (block.id && /^art-/.test(block.id))
          html = html.replace(
            /^<strong>(.+?)<\/strong>/,
            `<a class="law-device" href="${esc(route(id, block.id))}"><strong>$1</strong></a>`,
          );
        return `<p${dom}${target}${level ? ` class="law-${level}"` : ''}>${html}</p>`;
      })
      .join('');
  }

  function contents(id, blocks) {
    const articles = blocks.filter((block) => /^art-\d+(-[a-z])?$/.test(block.id || ''));
    const annexes = blocks.filter((block) => block.kind === 'annex' && block.id);
    const link = (block, label) =>
      `<li><a href="${esc(route(id, block.id))}" data-law-link="${esc(block.id)}">${esc(label)}</a></li>`;
    const parts = [];
    if (articles.length)
      parts.push(
        `<h2>Artigos</h2><ol>${articles.map((block) => link(block, labelOf(block) || block.id)).join('')}</ol>`,
      );
    if (annexes.length)
      parts.push(
        `<h2>Anexos</h2><ol>${annexes.map((block) => link(block, block.text.length > 60 ? block.text.slice(0, 58) + '…' : block.text)).join('')}</ol>`,
      );
    return parts.join('');
  }

  const ORIGINS = {
    pdf: 'cópia do PDF oficial',
    html_printed: 'cópia da página oficial',
    research_package: 'cópia do PDF oficial (pacote de pesquisa)',
    archived_pdf_extract: 'texto extraído do PDF oficial arquivado',
    archived_official_text: 'texto oficial arquivado no acervo',
  };

  function provenance(meta) {
    const source = meta.source;
    if (!source) return '';
    const parts = [ORIGINS[source.origin] || 'cópia de consulta'];
    if (source.retrievedAt) parts.push(`obtida em ${source.retrievedAt}`);
    if (source.sha256) parts.push(`SHA-256 ${String(source.sha256).slice(0, 12)}…`);
    return `<p class="law-provenance">Texto: ${esc(parts.join(' · '))}. Não substitui a publicação oficial nem altera a situação registrada do ato.</p>`;
  }

  // "Art. 2º e §§ 1º–2º" → art-2; "Anexo III, item 4" → anexo-iii.
  function anchorForClause(clause, anchors) {
    const text = String(clause || '');
    const article = text.match(/Arts?\.?\s*(\d+)/i);
    if (article && anchors.has(`art-${article[1]}`)) return `art-${article[1]}`;
    const annex = text.match(/Anexo\s+([IVXLC]+)\b/);
    if (annex && anchors.has(`anexo-${annex[1].toLowerCase()}`))
      return `anexo-${annex[1].toLowerCase()}`;
    if (/Anexo/i.test(text) && anchors.has('anexo-unico')) return 'anexo-unico';
    return null;
  }

  function files(id, meta) {
    const local = (path) => typeof path === 'string' && /^pdfs\/[\w./-]+\.pdf$/.test(path);
    const rows = [];
    const main = meta.source?.file;
    if (local(main))
      rows.push(
        `<li><a href="${esc(main)}" target="_blank" rel="noopener" data-law-pdf>PDF do ato</a></li>`,
      );
    (meta.annexFiles || []).forEach((annex, i) => {
      if (!local(annex.file)) return;
      const label = annex.kind === 'anexo' ? 'PDF dos anexos' : 'Documento complementar';
      const sections = (annex.sections || []).length ? ` (${annex.sections.join(', ')})` : '';
      rows.push(
        `<li><a href="${esc(annex.file)}" target="_blank" rel="noopener">${label}${meta.annexFiles.length > 1 ? ' ' + (i + 1) : ''}</a>${esc(sections)}</li>`,
      );
    });
    rows.push(
      `<li><a href="texts/${esc(id)}.md" download>Texto em Markdown</a></li>`,
      `<li>${safeLink(meta.officialUrl, 'Fonte oficial')}</li>`,
    );
    return `<section><h2>Arquivos</h2><ul class="law-files">${rows.join('')}</ul></section>`;
  }

  function context(id, record, anchors) {
    if (!record) return '';
    const requirements = (record.requirements || [])
      .map((requirement) => {
        const anchor = anchorForClause(requirement.clause, anchors);
        const where = requirement.clause
          ? anchor
            ? `<a href="${esc(route(id, anchor))}" data-law-link="${esc(anchor)}">${esc(requirement.clause)}</a>`
            : esc(requirement.clause)
          : '';
        return `<li><strong>${esc(requirement.title)}</strong>${where ? `<br>${where}` : ''}</li>`;
      })
      .join('');
    return `<section><h2>Situação registrada</h2>${regulatoryStatusSummary(record)}</section>${
      requirements
        ? `<section><h2>Requisitos extraídos</h2><ul class="law-requirements">${requirements}</ul></section>`
        : ''
    }${typeof documentConsultationLinks === 'function' ? documentConsultationLinks(record) : ''}`;
  }

  function focusAnchor(anchor, { scroll = true } = {}) {
    const main = $('#main');
    main.querySelectorAll('.law-target').forEach((el) => el.classList.remove('law-target'));
    main
      .querySelectorAll('[data-law-link][aria-current]')
      .forEach((el) => el.removeAttribute('aria-current'));
    if (!anchor || !ANCHOR.test(anchor)) return false;
    const target = document.getElementById('lei-' + anchor);
    if (!target) return false;
    target.classList.add('law-target');
    main
      .querySelectorAll(`[data-law-link="${anchor}"]`)
      .forEach((el) => el.setAttribute('aria-current', 'location'));
    if (scroll) {
      const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
      target.scrollIntoView({ behavior: reduced ? 'instant' : 'smooth', block: 'start' });
      target.focus({ preventScroll: true });
    }
    return true;
  }

  function searchIn(term) {
    const main = $('#main');
    const status = main.querySelector('[data-law-search-status]');
    main.querySelectorAll('.law-hit').forEach((el) => el.classList.remove('law-hit'));
    const query = norm(term.trim());
    if (query.length < 3) {
      status.textContent = '';
      return [];
    }
    const hits = [...main.querySelectorAll('.law-text > *')].filter((el) =>
      norm(el.textContent).includes(query),
    );
    hits.forEach((el) => el.classList.add('law-hit'));
    status.textContent = hits.length
      ? `${hits.length} trecho${hits.length > 1 ? 's' : ''}`
      : 'Nenhum trecho';
    return hits;
  }

  // Go to a device; a device that is not in this text is said, not ignored.
  function reach(anchor) {
    const main = $('#main');
    main.querySelector('[data-law-missing]')?.remove();
    if (!anchor || focusAnchor(anchor)) return;
    const note = document.createElement('p');
    note.className = 'notice portal-consultation-note';
    note.dataset.lawMissing = '';
    note.setAttribute('role', 'status');
    note.textContent =
      'O trecho indicado no link não foi localizado neste texto. A lei abre do início.';
    main.querySelector('.law-text').prepend(note);
    note.scrollIntoView({ block: 'center' });
  }

  async function render() {
    const main = $('#main');
    const params = new URLSearchParams(location.hash.split('?')[1] || '');
    const id = params.get('id') || '';
    const anchor = params.get('trecho');
    // Same act already on screen: only move to the requested device.
    if (current === id && main.querySelector(`[data-law="${CSS.escape(id)}"]`)) {
      reach(anchor);
      return;
    }
    current = null;
    if (!ID.test(id)) {
      main.innerHTML =
        '<div class="portal-empty"><h1 class="portal-title">Lei não encontrada</h1><p>O endereço não indica um ato do acervo.</p><a class="btn" href="#library">Ver todas as leis</a></div>';
      return;
    }
    main.innerHTML = '<p class="law-loading" role="status">Carregando o texto da lei…</p>';
    let text;
    let record = null;
    try {
      [text] = await Promise.all([
        load(id),
        typeof PdfCopies !== 'undefined' ? PdfCopies.load() : null,
      ]);
      record = typeof catalog !== 'undefined' ? catalogRecord(catalog, id) : null;
      if (record?._summary && record.regulatorySource)
        try {
          await loadRegulationRecord(record.regulatorySource, record.regulatoryId);
          record = catalogRecord(catalog, id);
        } catch {
          // The text is still readable without the detailed record.
        }
    } catch {
      main.innerHTML = `<div class="portal-empty"><h1 class="portal-title">Lei não encontrada</h1><p role="alert">Não há texto para “${esc(id)}” neste acervo.</p><a class="btn" href="#library">Ver todas as leis</a></div>`;
      return;
    }
    if (new URLSearchParams(location.hash.split('?')[1] || '').get('id') !== id) return;
    const { meta, blocks } = text;
    const anchors = new Set(blocks.map((block) => block.id).filter(Boolean));
    const title = record?.title || meta.title || id;
    const question = `Sobre ${title}: `;
    const toc = contents(id, blocks);
    main.innerHTML = `<div class="law-page" data-law="${esc(id)}" data-full-text="${meta.fullTextAvailable ? 'true' : 'false'}">
<header class="law-header">
<nav class="law-crumbs" aria-label="Caminho"><a href="#library">Leis</a> <span aria-hidden="true">/</span> ${esc(String(record?.issuer || record?.agency || meta.agency || '').toUpperCase())}</nav>
<h1 class="portal-title">${esc(title)}</h1>
${record?.summary ? `<p class="portal-summary">${esc(record.summary)}</p>` : ''}
<div class="law-actions portal-actions">
<a class="btn primary" href="${esc('#ia?' + new URLSearchParams({ q: question }))}">Perguntar sobre esta lei</a>
${typeof PdfCopies !== 'undefined' ? PdfCopies.link(id, 'btn') : ''}
${safeLink(meta.officialUrl, 'Fonte oficial', 'btn')}
</div>
${provenance(meta)}
</header>
<div class="law-layout">
<nav class="law-contents" aria-label="Sumário da lei">
<form class="law-search" role="search" data-law-search><label for="lawSearch">Buscar nesta lei</label><input id="lawSearch" type="search" autocomplete="off" placeholder="Palavra ou expressão"><span data-law-search-status role="status"></span></form>
${toc || '<p class="scope-note">Este texto não tem artigos numerados identificados.</p>'}
</nav>
<article class="law-text" aria-label="Texto da lei">${renderBlocks(id, blocks)}</article>
<aside class="law-context" aria-label="Contexto da lei">${files(id, meta)}${context(id, record, anchors)}</aside>
</div></div>`;
    current = id;
    let hits = [];
    let position = -1;
    const form = main.querySelector('[data-law-search]');
    form.querySelector('input').addEventListener('input', (event) => {
      hits = searchIn(event.target.value);
      position = -1;
    });
    form.addEventListener('submit', (event) => {
      event.preventDefault();
      if (!hits.length) return;
      position = (position + 1) % hits.length;
      hits[position].scrollIntoView({
        behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth',
        block: 'center',
      });
    });
    reach(anchor);
  }

  return { route, loadIndex, has, load, render, anchorForClause };
})();
LawReader.loadIndex();

function renderLaw() {
  return LawReader.render();
}
